def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found")
    return text.replace(old, new, 1)

SCHEMA_NEW.write_text('import {\n  boolean,\n  doublePrecision,\n  pgTable,\n  text,\n  timestamp,\n  uniqueIndex,\n  uuid,\n} from "drizzle-orm/pg-core";\nimport { executionWalletsTable } from "./execution";\n\nexport const copyTradeControlTable = pgTable(\n  "copy_trade_control",\n  {\n    id: text("id").primaryKey(),\n    enabled: boolean("enabled").notNull().default(false),\n    updatedAt: timestamp("updated_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n  },\n);\n\nexport const copyTradeSourcesTable = pgTable(\n  "copy_trade_sources",\n  {\n    id: uuid("id").defaultRandom().primaryKey(),\n    address: text("address").notNull().unique(),\n    enabled: boolean("enabled").notNull().default(true),\n    copyBuys: boolean("copy_buys").notNull().default(true),\n    copySells: boolean("copy_sells").notNull().default(true),\n    mode: text("mode").notNull().default("follow-source"),\n    maxBuyAmount: doublePrecision("max_buy_amount").notNull().default(0.1),\n    maxBuyCurrency: text("max_buy_currency").notNull().default("sol"),\n    slippagePct: doublePrecision("slippage_pct").notNull().default(2),\n    delayMs: doublePrecision("delay_ms").notNull().default(0),\n    autoTpPct: doublePrecision("auto_tp_pct").notNull().default(100),\n    autoTpSellPct: doublePrecision("auto_tp_sell_pct").notNull().default(50),\n    autoSlPct: doublePrecision("auto_sl_pct").notNull().default(30),\n    autoSlSellPct: doublePrecision("auto_sl_sell_pct").notNull().default(100),\n    lastSignature: text("last_signature"),\n    createdAt: timestamp("created_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n    updatedAt: timestamp("updated_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n  },\n);\n\nexport const copyTradeTargetsTable = pgTable(\n  "copy_trade_targets",\n  {\n    id: uuid("id").defaultRandom().primaryKey(),\n    sourceId: uuid("source_id")\n      .notNull()\n      .references(() => copyTradeSourcesTable.id, { onDelete: "cascade" }),\n    walletId: uuid("wallet_id")\n      .notNull()\n      .references(() => executionWalletsTable.id, { onDelete: "cascade" }),\n    enabled: boolean("enabled").notNull().default(true),\n    buyAmount: doublePrecision("buy_amount").notNull().default(0.01),\n    buyCurrency: text("buy_currency").notNull().default("sol"),\n    updatedAt: timestamp("updated_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n  },\n  (table) => ({\n    sourceWalletUnique: uniqueIndex("copy_trade_target_source_wallet_unique").on(\n      table.sourceId,\n      table.walletId,\n    ),\n  }),\n);\n\nexport const copyTradeEventsTable = pgTable(\n  "copy_trade_events",\n  {\n    id: uuid("id").defaultRandom().primaryKey(),\n    sourceId: uuid("source_id")\n      .notNull()\n      .references(() => copyTradeSourcesTable.id, { onDelete: "cascade" }),\n    sourceAddress: text("source_address").notNull(),\n    sourceSignature: text("source_signature").notNull(),\n    mint: text("mint").notNull(),\n    side: text("side").notNull(),\n    sourceSellPct: doublePrecision("source_sell_pct"),\n    status: text("status").notNull().default("detected"),\n    error: text("error"),\n    createdAt: timestamp("created_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n    updatedAt: timestamp("updated_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n  },\n  (table) => ({\n    sourceSignatureUnique: uniqueIndex("copy_trade_event_source_signature_unique").on(\n      table.sourceId,\n      table.sourceSignature,\n      table.mint,\n      table.side,\n    ),\n  }),\n);\n\nexport const copyTradeExecutionsTable = pgTable(\n  "copy_trade_executions",\n  {\n    id: uuid("id").defaultRandom().primaryKey(),\n    eventId: uuid("event_id")\n      .notNull()\n      .references(() => copyTradeEventsTable.id, { onDelete: "cascade" }),\n    walletId: uuid("wallet_id")\n      .notNull()\n      .references(() => executionWalletsTable.id, { onDelete: "cascade" }),\n    walletAddress: text("wallet_address").notNull(),\n    status: text("status").notNull().default("pending"),\n    amountSol: doublePrecision("amount_sol"),\n    sellPct: doublePrecision("sell_pct"),\n    signature: text("signature"),\n    error: text("error"),\n    createdAt: timestamp("created_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n    updatedAt: timestamp("updated_at", { withTimezone: true })\n      .notNull()\n      .defaultNow(),\n  },\n  (table) => ({\n    eventWalletUnique: uniqueIndex("copy_trade_execution_event_wallet_unique").on(\n      table.eventId,\n      table.walletId,\n    ),\n  }),\n);\n\nexport type CopyTradeSource = typeof copyTradeSourcesTable.$inferSelect;\nexport type CopyTradeTarget = typeof copyTradeTargetsTable.$inferSelect;\nexport type CopyTradeEvent = typeof copyTradeEventsTable.$inferSelect;\n')
ROUTES_NEW.write_text('import { Router, type IRouter } from "express";\nimport { timingSafeEqual } from "node:crypto";\nimport { PublicKey } from "@solana/web3.js";\nimport { and, desc, eq } from "drizzle-orm";\nimport {\n  db,\n  copyTradeControlTable,\n  copyTradeEventsTable,\n  copyTradeExecutionsTable,\n  copyTradeSourcesTable,\n  copyTradeTargetsTable,\n  executionWalletsTable,\n} from "@workspace/db";\n\nconst router: IRouter = Router();\n\nfunction authorized(value: string | undefined): boolean {\n  const expected = process.env.PANEL_API_TOKEN;\n  if (!expected || !value?.startsWith("Bearer ")) return false;\n\n  const actual = value.slice("Bearer ".length);\n  const a = Buffer.from(actual);\n  const b = Buffer.from(expected);\n\n  return a.length === b.length && timingSafeEqual(a, b);\n}\n\nrouter.use((req, res, next) => {\n  if (!authorized(req.headers.authorization)) {\n    res.status(401).json({ error: "Unauthorized" });\n    return;\n  }\n  next();\n});\n\nasync function ensureControl() {\n  const rows = await db\n    .insert(copyTradeControlTable)\n    .values({ id: "global", enabled: false })\n    .onConflictDoNothing()\n    .returning();\n\n  if (rows[0]) return rows[0];\n\n  const existing = await db\n    .select()\n    .from(copyTradeControlTable)\n    .where(eq(copyTradeControlTable.id, "global"))\n    .limit(1);\n\n  return existing[0];\n}\n\nasync function fullState() {\n  const control = await ensureControl();\n\n  const sources = await db\n    .select()\n    .from(copyTradeSourcesTable);\n\n  const targets = await db\n    .select()\n    .from(copyTradeTargetsTable);\n\n  const wallets = await db\n    .select()\n    .from(executionWalletsTable);\n\n  const walletById = new Map(\n    wallets.map((wallet) => [wallet.id, wallet]),\n  );\n\n  const events = await db\n    .select()\n    .from(copyTradeEventsTable)\n    .orderBy(desc(copyTradeEventsTable.createdAt))\n    .limit(25);\n\n  const eventIds = new Set(events.map((event) => event.id));\n  const allExecutions = await db\n    .select()\n    .from(copyTradeExecutionsTable)\n    .orderBy(desc(copyTradeExecutionsTable.createdAt))\n    .limit(150);\n\n  const executions = allExecutions.filter((item) =>\n    eventIds.has(item.eventId),\n  );\n\n  return {\n    enabled: control?.enabled ?? false,\n    sources: sources.map((source) => ({\n      ...source,\n      targets: targets\n        .filter((target) => target.sourceId === source.id)\n        .map((target) => ({\n          ...target,\n          address: walletById.get(target.walletId)?.address ?? "",\n          walletEnabled:\n            walletById.get(target.walletId)?.enabled ?? false,\n        })),\n    })),\n    history: events.map((event) => ({\n      ...event,\n      executions: executions.filter(\n        (item) => item.eventId === event.id,\n      ),\n    })),\n  };\n}\n\nrouter.get("/copy-trading", async (_req, res): Promise<void> => {\n  res.json(await fullState());\n});\n\nrouter.post("/copy-trading/control", async (req, res): Promise<void> => {\n  const { enabled } = req.body ?? {};\n\n  if (typeof enabled !== "boolean") {\n    res.status(400).json({ error: "enabled must be boolean" });\n    return;\n  }\n\n  const current = await ensureControl();\n\n  await db\n    .insert(copyTradeControlTable)\n    .values({\n      id: "global",\n      enabled,\n      updatedAt: new Date(),\n    })\n    .onConflictDoUpdate({\n      target: copyTradeControlTable.id,\n      set: {\n        enabled,\n        updatedAt: new Date(),\n      },\n    });\n\n  if (enabled && !current?.enabled) {\n    await db\n      .update(copyTradeSourcesTable)\n      .set({\n        lastSignature: null,\n        updatedAt: new Date(),\n      });\n  }\n\n  res.json(await fullState());\n});\n\nrouter.post("/copy-trading/source", async (req, res): Promise<void> => {\n  const address =\n    typeof req.body?.address === "string"\n      ? req.body.address.trim()\n      : "";\n\n  try {\n    new PublicKey(address);\n  } catch {\n    res.status(400).json({ error: "Invalid Solana source wallet" });\n    return;\n  }\n\n  const executionWallet = await db\n    .select()\n    .from(executionWalletsTable)\n    .where(eq(executionWalletsTable.address, address))\n    .limit(1);\n\n  if (executionWallet[0]) {\n    res.status(409).json({\n      error: "An execution wallet cannot also be a copy source",\n    });\n    return;\n  }\n\n  const inserted = await db\n    .insert(copyTradeSourcesTable)\n    .values({\n      address,\n      enabled: true,\n      copyBuys: true,\n      copySells: true,\n      mode: "follow-source",\n      maxBuyAmount: 0.1,\n      maxBuyCurrency: "sol",\n      slippagePct: 2,\n      delayMs: 0,\n      updatedAt: new Date(),\n    })\n    .onConflictDoNothing()\n    .returning();\n\n  if (!inserted[0]) {\n    res.status(409).json({ error: "Source wallet already exists" });\n    return;\n  }\n\n  const wallets = await db\n    .select()\n    .from(executionWalletsTable);\n\n  for (const wallet of wallets) {\n    await db\n      .insert(copyTradeTargetsTable)\n      .values({\n        sourceId: inserted[0].id,\n        walletId: wallet.id,\n        enabled: wallet.enabled,\n        buyAmount: 0.01,\n        buyCurrency: "sol",\n      })\n      .onConflictDoNothing();\n  }\n\n  res.status(201).json(await fullState());\n});\n\nrouter.post("/copy-trading/source/:id", async (req, res): Promise<void> => {\n  const sourceRows = await db\n    .select()\n    .from(copyTradeSourcesTable)\n    .where(eq(copyTradeSourcesTable.id, req.params.id))\n    .limit(1);\n\n  const source = sourceRows[0];\n\n  if (!source) {\n    res.status(404).json({ error: "Copy source not found" });\n    return;\n  }\n\n  const {\n    enabled,\n    copyBuys,\n    copySells,\n    mode,\n    maxBuyAmount,\n    maxBuyCurrency,\n    slippagePct,\n    delayMs,\n    autoTpPct,\n    autoTpSellPct,\n    autoSlPct,\n    autoSlSellPct,\n    targets,\n  } = req.body ?? {};\n\n  if (\n    typeof enabled !== "boolean" ||\n    typeof copyBuys !== "boolean" ||\n    typeof copySells !== "boolean" ||\n    !["follow-source", "copy-buy-auto"].includes(mode) ||\n    !["sol", "usd"].includes(maxBuyCurrency)\n  ) {\n    res.status(400).json({ error: "Invalid copy source settings" });\n    return;\n  }\n\n  const numbers = {\n    maxBuyAmount: Number(maxBuyAmount),\n    slippagePct: Number(slippagePct),\n    delayMs: Number(delayMs),\n    autoTpPct: Number(autoTpPct),\n    autoTpSellPct: Number(autoTpSellPct),\n    autoSlPct: Number(autoSlPct),\n    autoSlSellPct: Number(autoSlSellPct),\n  };\n\n  if (\n    !Number.isFinite(numbers.maxBuyAmount) ||\n    numbers.maxBuyAmount <= 0 ||\n    !Number.isFinite(numbers.slippagePct) ||\n    numbers.slippagePct <= 0 ||\n    numbers.slippagePct > 50 ||\n    !Number.isFinite(numbers.delayMs) ||\n    numbers.delayMs < 0 ||\n    numbers.delayMs > 15000 ||\n    !Number.isFinite(numbers.autoTpPct) ||\n    numbers.autoTpPct <= 0 ||\n    !Number.isFinite(numbers.autoTpSellPct) ||\n    numbers.autoTpSellPct <= 0 ||\n    numbers.autoTpSellPct > 100 ||\n    !Number.isFinite(numbers.autoSlPct) ||\n    numbers.autoSlPct <= 0 ||\n    !Number.isFinite(numbers.autoSlSellPct) ||\n    numbers.autoSlSellPct <= 0 ||\n    numbers.autoSlSellPct > 100\n  ) {\n    res.status(400).json({ error: "Invalid numeric copy settings" });\n    return;\n  }\n\n  await db\n    .update(copyTradeSourcesTable)\n    .set({\n      enabled,\n      copyBuys,\n      copySells,\n      mode,\n      maxBuyAmount: numbers.maxBuyAmount,\n      maxBuyCurrency,\n      slippagePct: numbers.slippagePct,\n      delayMs: numbers.delayMs,\n      autoTpPct: numbers.autoTpPct,\n      autoTpSellPct: numbers.autoTpSellPct,\n      autoSlPct: numbers.autoSlPct,\n      autoSlSellPct: numbers.autoSlSellPct,\n      lastSignature:\n        enabled && !source.enabled\n          ? null\n          : source.lastSignature,\n      updatedAt: new Date(),\n    })\n    .where(eq(copyTradeSourcesTable.id, source.id));\n\n  if (Array.isArray(targets)) {\n    for (const item of targets) {\n      if (\n        typeof item?.walletId !== "string" ||\n        typeof item?.enabled !== "boolean" ||\n        !["sol", "usd"].includes(item?.buyCurrency)\n      ) {\n        continue;\n      }\n\n      const amount = Number(item.buyAmount);\n      if (!Number.isFinite(amount) || amount <= 0) continue;\n\n      await db\n        .insert(copyTradeTargetsTable)\n        .values({\n          sourceId: source.id,\n          walletId: item.walletId,\n          enabled: item.enabled,\n          buyAmount: amount,\n          buyCurrency: item.buyCurrency,\n          updatedAt: new Date(),\n        })\n        .onConflictDoUpdate({\n          target: [\n            copyTradeTargetsTable.sourceId,\n            copyTradeTargetsTable.walletId,\n          ],\n          set: {\n            enabled: item.enabled,\n            buyAmount: amount,\n            buyCurrency: item.buyCurrency,\n            updatedAt: new Date(),\n          },\n        });\n    }\n  }\n\n  res.json(await fullState());\n});\n\nrouter.delete("/copy-trading/source/:id", async (req, res): Promise<void> => {\n  const deleted = await db\n    .delete(copyTradeSourcesTable)\n    .where(eq(copyTradeSourcesTable.id, req.params.id))\n    .returning({ id: copyTradeSourcesTable.id });\n\n  if (!deleted[0]) {\n    res.status(404).json({ error: "Copy source not found" });\n    return;\n  }\n\n  res.json(await fullState());\n});\n\nexport default router;\n')
WORKER_NEW.write_text('import { and, eq } from "drizzle-orm";\nimport { PublicKey } from "@solana/web3.js";\nimport {\n  db,\n  copyTradeControlTable,\n  copyTradeEventsTable,\n  copyTradeExecutionsTable,\n  copyTradeSourcesTable,\n  copyTradeTargetsTable,\n  executionStrategiesTable,\n  executionWalletsTable,\n  type CopyTradeSource,\n} from "@workspace/db";\nimport { decryptSecret } from "./execution-vault";\nimport {\n  currentSolUsd,\n  executeBuy,\n  executeSellPercent,\n  executionConnection,\n  walletTokenBalance,\n} from "./execution-engine";\nimport {\n  recordBuyAccounting,\n  recordSellAccounting,\n} from "./position-accounting";\nimport { Keypair } from "@solana/web3.js";\nimport { logger } from "./logger";\n\nconst SOL_EPSILON = 0.00001;\nconst POLL_MS = 1800;\nconst WSOL_MINT = "So11111111111111111111111111111111111111112";\n\ntype DetectedTrade = {\n  mint: string;\n  side: "buy" | "sell";\n  sellPct: number | null;\n};\n\nfunction amount(balance: any): number {\n  const value =\n    balance?.uiTokenAmount?.uiAmountString ??\n    balance?.uiTokenAmount?.uiAmount ??\n    "0";\n\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? parsed : 0;\n}\n\nfunction ownedTokenBalances(items: readonly any[] | null | undefined, owner: string) {\n  const map = new Map<string, number>();\n\n  for (const item of items ?? []) {\n    if (String(item?.owner ?? "") !== owner) continue;\n    if (!item?.mint || item.mint === WSOL_MINT) continue;\n\n    map.set(\n      item.mint,\n      (map.get(item.mint) ?? 0) + amount(item),\n    );\n  }\n\n  return map;\n}\n\nasync function detectTrade(\n  sourceAddress: string,\n  signature: string,\n): Promise<DetectedTrade | null> {\n  const tx = await executionConnection.getParsedTransaction(\n    signature,\n    {\n      commitment: "confirmed",\n      maxSupportedTransactionVersion: 0,\n    },\n  );\n\n  if (!tx?.meta || tx.meta.err) return null;\n\n  const keys = tx.transaction.message.accountKeys;\n  const ownerIndex = keys.findIndex(\n    (item) => item.pubkey.toBase58() === sourceAddress,\n  );\n\n  if (ownerIndex < 0) return null;\n\n  const beforeLamports = tx.meta.preBalances[ownerIndex];\n  const afterLamports = tx.meta.postBalances[ownerIndex];\n\n  if (\n    beforeLamports == null ||\n    afterLamports == null\n  ) {\n    return null;\n  }\n\n  const solDelta =\n    (afterLamports - beforeLamports) / 1_000_000_000;\n\n  const pre = ownedTokenBalances(\n    tx.meta.preTokenBalances,\n    sourceAddress,\n  );\n\n  const post = ownedTokenBalances(\n    tx.meta.postTokenBalances,\n    sourceAddress,\n  );\n\n  const mints = new Set([...pre.keys(), ...post.keys()]);\n  const deltas = [...mints].map((mint) => ({\n    mint,\n    before: pre.get(mint) ?? 0,\n    after: post.get(mint) ?? 0,\n    delta: (post.get(mint) ?? 0) - (pre.get(mint) ?? 0),\n  }));\n\n  if (solDelta < -SOL_EPSILON) {\n    const buys = deltas\n      .filter((item) => item.delta > 0)\n      .sort((a, b) => b.delta - a.delta);\n\n    if (buys.length === 1) {\n      return {\n        mint: buys[0].mint,\n        side: "buy",\n        sellPct: null,\n      };\n    }\n  }\n\n  if (solDelta > SOL_EPSILON) {\n    const sells = deltas\n      .filter((item) => item.delta < 0 && item.before > 0)\n      .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));\n\n    if (sells.length === 1) {\n      return {\n        mint: sells[0].mint,\n        side: "sell",\n        sellPct: Math.min(\n          100,\n          Math.max(\n            0,\n            (Math.abs(sells[0].delta) / sells[0].before) * 100,\n          ),\n        ),\n      };\n    }\n  }\n\n  return null;\n}\n\nasync function findStrategy(walletId: string, mint: string) {\n  const rows = await db\n    .select()\n    .from(executionStrategiesTable)\n    .where(\n      and(\n        eq(executionStrategiesTable.walletId, walletId),\n        eq(executionStrategiesTable.mint, mint),\n      ),\n    )\n    .limit(1);\n\n  return rows[0] ?? null;\n}\n\nasync function amountToSol(\n  value: number,\n  currency: string,\n  solUsd: number | null,\n) {\n  if (currency === "usd") {\n    const rate = solUsd ?? await currentSolUsd();\n    return value / rate;\n  }\n\n  return value;\n}\n\nasync function processDetectedTrade(\n  source: CopyTradeSource,\n  sourceSignature: string,\n  trade: DetectedTrade,\n) {\n  if (trade.side === "buy" && !source.copyBuys) return;\n  if (trade.side === "sell" && !source.copySells) return;\n  if (trade.side === "sell" && source.mode === "copy-buy-auto") return;\n\n  const inserted = await db\n    .insert(copyTradeEventsTable)\n    .values({\n      sourceId: source.id,\n      sourceAddress: source.address,\n      sourceSignature,\n      mint: trade.mint,\n      side: trade.side,\n      sourceSellPct: trade.sellPct,\n      status: "detected",\n      updatedAt: new Date(),\n    })\n    .onConflictDoNothing()\n    .returning();\n\n  const event = inserted[0];\n  if (!event) return;\n\n  const targets = await db\n    .select()\n    .from(copyTradeTargetsTable)\n    .where(\n      and(\n        eq(copyTradeTargetsTable.sourceId, source.id),\n        eq(copyTradeTargetsTable.enabled, true),\n      ),\n    );\n\n  let ok = 0;\n  let failed = 0;\n  let skipped = 0;\n  let cachedSolUsd: number | null = null;\n\n  for (const target of targets) {\n    const walletRows = await db\n      .select()\n      .from(executionWalletsTable)\n      .where(eq(executionWalletsTable.id, target.walletId))\n      .limit(1);\n\n    const wallet = walletRows[0];\n\n    if (!wallet?.enabled) {\n      skipped += 1;\n      await db.insert(copyTradeExecutionsTable).values({\n        eventId: event.id,\n        walletId: target.walletId,\n        walletAddress: wallet?.address ?? "unknown",\n        status: "skipped",\n        error: "Execution wallet is disabled",\n      });\n      continue;\n    }\n\n    if (source.delayMs > 0) {\n      await new Promise((resolve) =>\n        setTimeout(resolve, Math.min(15000, source.delayMs)),\n      );\n    }\n\n    try {\n      const keypair = Keypair.fromSecretKey(\n        decryptSecret(wallet.encryptedSecret),\n      );\n\n      const strategy = await findStrategy(wallet.id, trade.mint);\n\n      if (strategy?.state === "executing") {\n        throw new Error(\n          "AUTO/manual execution is already running for this position",\n        );\n      }\n\n      if (trade.side === "buy") {\n        if (\n          target.buyCurrency === "usd" ||\n          source.maxBuyCurrency === "usd"\n        ) {\n          cachedSolUsd = cachedSolUsd ?? await currentSolUsd();\n        }\n\n        const requestedSol = await amountToSol(\n          target.buyAmount,\n          target.buyCurrency,\n          cachedSolUsd,\n        );\n\n        const maxSol = await amountToSol(\n          source.maxBuyAmount,\n          source.maxBuyCurrency,\n          cachedSolUsd,\n        );\n\n        const buySol = Math.min(requestedSol, maxSol);\n\n        if (!Number.isFinite(buySol) || buySol <= 0) {\n          throw new Error("Invalid copy BUY amount");\n        }\n\n        const beforeBalance = await walletTokenBalance(\n          wallet.address,\n          trade.mint,\n        );\n\n        const signature = await executeBuy(\n          keypair,\n          trade.mint,\n          buySol,\n          source.slippagePct,\n        );\n\n        await recordBuyAccounting({\n          walletId: wallet.id,\n          address: wallet.address,\n          mint: trade.mint,\n          amountSol: buySol,\n          beforeBalance,\n          previousStrategy: strategy,\n        });\n\n        if (source.mode === "copy-buy-auto") {\n          await db\n            .update(executionStrategiesTable)\n            .set({\n              enabled: true,\n              tpPct: source.autoTpPct,\n              tpSellPct: source.autoTpSellPct,\n              slPct: source.autoSlPct,\n              slSellPct: source.autoSlSellPct,\n              state: "watching",\n              lastError: null,\n              updatedAt: new Date(),\n            })\n            .where(\n              and(\n                eq(executionStrategiesTable.walletId, wallet.id),\n                eq(executionStrategiesTable.mint, trade.mint),\n              ),\n            );\n        } else {\n          await db\n            .update(executionStrategiesTable)\n            .set({\n              enabled: false,\n              state: "idle",\n              lastError: null,\n              updatedAt: new Date(),\n            })\n            .where(\n              and(\n                eq(executionStrategiesTable.walletId, wallet.id),\n                eq(executionStrategiesTable.mint, trade.mint),\n              ),\n            );\n        }\n\n        await db.insert(copyTradeExecutionsTable).values({\n          eventId: event.id,\n          walletId: wallet.id,\n          walletAddress: wallet.address,\n          status: "copied",\n          amountSol: buySol,\n          signature,\n          updatedAt: new Date(),\n        });\n\n        ok += 1;\n      } else {\n        const sellPct = trade.sellPct ?? 0;\n\n        if (sellPct <= 0) {\n          throw new Error("Source SELL percentage could not be determined");\n        }\n\n        const beforeBalance = await walletTokenBalance(\n          wallet.address,\n          trade.mint,\n        );\n\n        if (beforeBalance <= 0) {\n          skipped += 1;\n          await db.insert(copyTradeExecutionsTable).values({\n            eventId: event.id,\n            walletId: wallet.id,\n            walletAddress: wallet.address,\n            status: "skipped",\n            sellPct,\n            error: "Wallet has no balance of the source token",\n          });\n          continue;\n        }\n\n        if (strategy?.enabled) {\n          await db\n            .update(executionStrategiesTable)\n            .set({\n              state: "executing",\n              updatedAt: new Date(),\n            })\n            .where(eq(executionStrategiesTable.id, strategy.id));\n        }\n\n        const signature = await executeSellPercent(\n          keypair,\n          trade.mint,\n          sellPct,\n          source.slippagePct,\n        );\n\n        await recordSellAccounting({\n          strategy,\n          address: wallet.address,\n          mint: trade.mint,\n          beforeBalance,\n          percentage: sellPct,\n          signature,\n          trigger: "copy-source-sell",\n          forceDisable: false,\n        });\n\n        await db.insert(copyTradeExecutionsTable).values({\n          eventId: event.id,\n          walletId: wallet.id,\n          walletAddress: wallet.address,\n          status: "copied",\n          sellPct,\n          signature,\n          updatedAt: new Date(),\n        });\n\n        ok += 1;\n      }\n    } catch (error) {\n      failed += 1;\n\n      await db.insert(copyTradeExecutionsTable).values({\n        eventId: event.id,\n        walletId: target.walletId,\n        walletAddress: wallet.address,\n        status: "failed",\n        error:\n          error instanceof Error\n            ? error.message\n            : String(error),\n        updatedAt: new Date(),\n      });\n\n      logger.error(\n        {\n          err: error,\n          source: source.address,\n          target: wallet.address,\n          mint: trade.mint,\n          side: trade.side,\n        },\n        "Copy trade execution failed",\n      );\n    }\n  }\n\n  const status =\n    ok > 0 && failed === 0\n      ? "completed"\n      : ok > 0\n        ? "partial"\n        : failed > 0\n          ? "failed"\n          : "skipped";\n\n  await db\n    .update(copyTradeEventsTable)\n    .set({\n      status,\n      error:\n        failed > 0\n          ? `${failed} target(s) failed; ${skipped} skipped`\n          : skipped > 0\n            ? `${skipped} target(s) skipped`\n            : null,\n      updatedAt: new Date(),\n    })\n    .where(eq(copyTradeEventsTable.id, event.id));\n}\n\nasync function pollSource(source: CopyTradeSource) {\n  let sourceKey: PublicKey;\n\n  try {\n    sourceKey = new PublicKey(source.address);\n  } catch {\n    return;\n  }\n\n  const signatures = await executionConnection.getSignaturesForAddress(\n    sourceKey,\n    { limit: 25 },\n    "confirmed",\n  );\n\n  if (signatures.length === 0) return;\n\n  if (!source.lastSignature) {\n    await db\n      .update(copyTradeSourcesTable)\n      .set({\n        lastSignature: signatures[0].signature,\n        updatedAt: new Date(),\n      })\n      .where(eq(copyTradeSourcesTable.id, source.id));\n    return;\n  }\n\n  const pending = [];\n\n  for (const item of signatures) {\n    if (item.signature === source.lastSignature) break;\n    pending.push(item);\n  }\n\n  for (const item of pending.reverse()) {\n    try {\n      const trade = await detectTrade(\n        source.address,\n        item.signature,\n      );\n\n      if (trade) {\n        await processDetectedTrade(\n          source,\n          item.signature,\n          trade,\n        );\n      }\n    } catch (error) {\n      logger.error(\n        {\n          err: error,\n          source: source.address,\n          signature: item.signature,\n        },\n        "Copy trade source transaction failed",\n      );\n    }\n\n    await db\n      .update(copyTradeSourcesTable)\n      .set({\n        lastSignature: item.signature,\n        updatedAt: new Date(),\n      })\n      .where(eq(copyTradeSourcesTable.id, source.id));\n  }\n}\n\nlet running = false;\n\nasync function tick() {\n  if (running) return;\n  running = true;\n\n  try {\n    const controlRows = await db\n      .select()\n      .from(copyTradeControlTable)\n      .where(eq(copyTradeControlTable.id, "global"))\n      .limit(1);\n\n    if (!controlRows[0]?.enabled) return;\n\n    const sources = await db\n      .select()\n      .from(copyTradeSourcesTable)\n      .where(eq(copyTradeSourcesTable.enabled, true));\n\n    for (const source of sources) {\n      try {\n        await pollSource(source);\n      } catch (error) {\n        logger.error(\n          { err: error, source: source.address },\n          "Copy source poll failed",\n        );\n      }\n    }\n  } finally {\n    running = false;\n  }\n}\n\nexport function startCopyTradingWorker() {\n  void tick();\n  setInterval(() => void tick(), POLL_MS);\n}\n')

